import{_ as p,a0 as t,w as o,s as u,ao as c,I as l,x as s,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"一窺你安裝的 Linux 軟件包 | LCTT x X-CMD","titleTemplate":false,"description":"一窺你安裝的 Linux 軟件包 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一窺你安裝的 Linux 軟件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一窺你安裝的 Linux 軟件包 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20171214 Peeking into your Linux packages","title":"一窺你安裝的 Linux 軟件包","tag":"201810","desc":""},"relativePath":"201810/20171214 Peeking into your Linux packages.md","filePath":"[post].md"}'),r={name:"201810/20171214 Peeking into your Linux packages.md"};function d(g,n,k,h,b,f){const a=t("Link");return o(),u("div",null,[n[13]||(n[13]=c(`<h1 id="一窺你安裝的-linux-軟件包" tabindex="-1">一窺你安裝的 Linux 軟件包 <a class="header-anchor" href="#一窺你安裝的-linux-軟件包" aria-label="Permalink to “一窺你安裝的 Linux 軟件包”">​</a></h1><blockquote><p>這些最有用的命令可以讓你瞭解安裝在你的 Debian 類的 Linux 系統上的包的情況。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2017/12/christmas-packages-100744371-large.jpg" alt=""></p><p>你有沒有想過你的 Linux 系統上安裝了幾千個軟件包？ 是的，我説的是“千”。 即使是相當一般的 Linux 系統也可能安裝了上千個軟件包。 有很多方法可以獲得這些包到底是什麼包的詳細信息。</p><p>首先，要在基於 Debian 的發行版（如 Ubuntu）上快速得到已安裝的軟件包數量，請使用 <code>apt list --installed</code>， 如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt list --installed | wc -l</span></span>
<span class="line"><span>2067</span></span></code></pre></div><p>這個數字實際上多了一個，因為輸出中包含了 “Listing ...” 作為它的第一行。 這個命令會更準確：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt list --installed | grep -v &quot;^Listing&quot; | wc -l</span></span>
<span class="line"><span>2066</span></span></code></pre></div><p>要獲得所有這些包的詳細信息，請按以下方式瀏覽列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt list --installed | more</span></span>
<span class="line"><span>Listing...</span></span>
<span class="line"><span>a11y-profile-manager-indicator/xenial,now 0.1.10-0ubuntu3 amd64 [installed]</span></span>
<span class="line"><span>account-plugin-aim/xenial,now 3.12.11-0ubuntu3 amd64 [installed]</span></span>
<span class="line"><span>account-plugin-facebook/xenial,xenial,now 0.12+16.04.20160126-0ubuntu1 all [installed]</span></span>
<span class="line"><span>account-plugin-flickr/xenial,xenial,now 0.12+16.04.20160126-0ubuntu1 all [installed]</span></span>
<span class="line"><span>account-plugin-google/xenial,xenial,now 0.12+16.04.20160126-0ubuntu1 all [installed]</span></span>
<span class="line"><span>account-plugin-jabber/xenial,now 3.12.11-0ubuntu3 amd64 [installed]</span></span>
<span class="line"><span>account-plugin-salut/xenial,now 3.12.11-0ubuntu3 amd64 [installed]</span></span></code></pre></div><p>這需要觀察很多細節 —— 特別是讓你的眼睛在所有 2000 多個文件中徘徊。 它包含包名稱、版本等，以及更多但並不是以最易於我們人類解析的顯示信息。 <code>dpkg-query</code> 使得描述更容易理解，但這些描述會塞滿你的命令窗口，除非窗口非常寬。 因此，為了讓此篇文章更容易閲讀，下面的數據顯示已經分成了左右兩側。</p><p>左側：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dpkg-query -l | more</span></span>
<span class="line"><span>Desired=Unknown/Install/Remove/Purge/Hold</span></span>
<span class="line"><span>| Status=Not/Inst/Conf-files/Unpacked/halF-conf/Half-inst/trig-aWait/Trig-pend</span></span>
<span class="line"><span>|/ Err?=(none)/Reinst-required (Status,Err: uppercase=bad)</span></span>
<span class="line"><span>||/ Name                                                 Version                                      </span></span>
<span class="line"><span>+++-==============================================-=================================-</span></span>
<span class="line"><span>ii  a11y-profile-manager-indicator                 0.1.10-0ubuntu3                              </span></span>
<span class="line"><span>ii  account-plugin-aim                             3.12.11-0ubuntu3                             </span></span>
<span class="line"><span>ii  account-plugin-facebook                        0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>ii  account-plugin-flickr                          0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>ii  account-plugin-google                          0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>ii  account-plugin-jabber                          3.12.11-0ubuntu3                             </span></span>
<span class="line"><span>ii  account-plugin-salut                           3.12.11-0ubuntu3                             </span></span>
<span class="line"><span>ii  account-plugin-twitter                         0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>rc  account-plugin-windows-live                    0.11+14.04.20140409.1-0ubuntu2</span></span></code></pre></div><p>右側：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Architecture Description</span></span>
<span class="line"><span>============-=====================================================================</span></span>
<span class="line"><span>amd64        Accessibility Profile Manager - Unity desktop indicator</span></span>
<span class="line"><span>amd64        Messaging account plugin for AIM</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - facebook</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - flickr</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon</span></span>
<span class="line"><span>amd64        Messaging account plugin for Jabber/XMPP</span></span>
<span class="line"><span>amd64        Messaging account plugin for Local XMPP (Salut)</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - twitter</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - windows live</span></span></code></pre></div><p>每行開頭的 <code>ii</code> 和 <code>rc</code> 名稱（見上文“左側”）是包狀態指示符。 第一個字母表示包的預期狀態：</p><ul><li><code>u</code> -- 未知</li><li><code>i</code> -- 安裝</li><li><code>r</code> -- 移除/反安裝</li><li><code>p</code> -- 清除（也包括配置文件）</li><li><code>h</code> -- 保留</li></ul><p>第二個代表包的當前狀態：</p><ul><li><code>n</code> -- 未安裝</li><li><code>i</code> -- 已安裝</li><li><code>c</code> -- 配置文件（只安裝了配置文件）</li><li><code>U</code> -- 未打包</li><li><code>F</code> -- 半配置（出於某些原因配置失敗）</li><li><code>h</code> -- 半安裝（出於某些原因配置失敗）</li><li><code>W</code> -- 等待觸發（該包等待另外一個包的觸發器）</li><li><code>t</code> -- 待定觸發（該包被觸發）</li></ul><p>在通常的雙字符字段末尾添加的 <code>R</code> 表示需要重新安裝。 你可能永遠不會碰到這些。</p><p>快速查看整體包狀態的一種簡單方法是計算在不同狀態中包含的包的數量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dpkg-query -l | tail -n +6 | awk &#39;{print $1}&#39; | sort | uniq -c</span></span>
<span class="line"><span> 2066 ii</span></span>
<span class="line"><span> 134 rc</span></span></code></pre></div><p>我從上面的 <code>dpkg-query</code> 輸出中排除了前五行，因為這些是標題行，會混淆輸出。</p><p>這兩行基本上告訴我們，在這個系統上，應該安裝了 2066 個軟件包，而 134 個其他的軟件包已被刪除，但留下了配置文件。 你始終可以使用以下命令刪除程序包的剩餘配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg --purge xfont-mathml</span></span></code></pre></div><p>請注意，如果程序包二進制文件和配置文件都已經安裝了，則上面的命令將兩者都刪除。</p><hr>`,27)),l("p",null,[n[1]||(n[1]=s("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3242808/linux/peeking-into-your-linux-packages.html"},{default:e(()=>[...n[0]||(n[0]=[s("https://www.networkworld.com/article/3242808/linux/peeking-into-your-linux-packages.html",-1)])]),_:1})]),l("p",null,[n[5]||(n[5]=s("作者：",-1)),i(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...n[2]||(n[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),n[6]||(n[6]=s(" 譯者：",-1)),i(a,{href:"https://github.com/Flowsnow"},{default:e(()=>[...n[3]||(n[3]=[s("Flowsnow",-1)])]),_:1}),n[7]||(n[7]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[4]||(n[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[n[10]||(n[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[8]||(n[8]=[s("LCTT",-1)])]),_:1}),n[11]||(n[11]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...n[9]||(n[9]=[s("Linux中國",-1)])]),_:1}),n[12]||(n[12]=s(" 榮譽推出",-1))])])}const w=p(r,[["render",d]]);export{C as __pageData,w as default};
